mapper.select:
SELECT FROM practice_sessions ps JOIN songs s ON s.id = ps.song_id JOIN evaluations e ON e.session_id = ps.id WHERE ps.user_id = #{userId} AND ps.song_id = #{songId} AND ps.saved_at IS NOT NULL AND ps.record_deleted_at IS NULL
ORDER BY ps.started_at DESC, ps.id DESC ORDER BY ps.started_at ASC, ps.id ASC
LIMIT #{limit} OFFSET #{offset}

mapper.update:
UPDATE practice_sessions
SET saved_at = COALESCE(saved_at, #{savedAt}), memo = #{memo}
WHERE id = #{sessionId} AND user_id = #{userId} AND status = 'DONE' AND record_deleted_at IS NULL
